import { createHash, randomUUID } from 'node:crypto';
import { ObjectId, type ClientSession } from 'mongodb';
import sharp from 'sharp';
import { getDatabaseClient, getDb } from '../../infrastructure/database';
import { maxCoverArtInputBytes, maxCoverArtInputPixels, validateCoverArtFile } from '../../services/image/imageStorageService';
import { normalizeUtf8Text } from '../../utils/textEncoding';
import { AdminCatalogError, adminCatalogKind, readAdminCatalogRecord, withCurrentAdministrator, type AdminCatalogKind } from './adminCatalogService';
import { ADMIN_IMPORT_LIMITS, objectId, uuid } from '../import/adminImportContract';
import { importDigest } from '../import/adminImportService';
import { importPrivateStorageReady, importUploadSettled, type ImportAsset } from '../import/adminImportMediaTypes';
import { defaultImportObjectStorage, importAssetTarget, type ImportObjectIdentity, type ImportObjectStorage } from '../import/adminImportStorage';
import { checkAdminWorker } from '../adminWorkerLifecycle';

export type CatalogCoverKind = Exclude<AdminCatalogKind, 'organization'>;
/** One staged image uploaded from this computer for one catalog item and its uploader; serves at most one approval. */
export interface CatalogCoverUpload {
    _id: ObjectId; kind: CatalogCoverKind; ownerId: string; actorId: string; operationId: string; fingerprint: string;
    asset: ImportAsset; usedBy: string | null; createdAt: Date; updatedAt: Date;
    /** The cleanup pass's lease; while unused it first frees a day after upload. `asset.leaseOwner/leaseUntil` belong to the transfer. */
    leaseOwner: string | null; leaseUntil: Date | null;
}
/** Per-administrator unused bound, unused lifetime, keep/failure retry delay and cleanup lease (published in admin-workbench.md). */
export const COVER_UPLOAD_LIMITS = Object.freeze({ unused: 16, unusedMs: 86_400_000, retryMs: 3_600_000, leaseMs: 300_000 });
export const CATALOG_COVER_UPLOAD_COLLECTION = 'adminCatalogCoverUploads';

const uploads = () => getDb()!.collection<CatalogCoverUpload>(CATALOG_COVER_UPLOAD_COLLECTION);
/** Every state whose object may still exist; only `deleted` is final. */
const liveStates = ['pending', 'unknown', 'ready', 'deleting', 'cleanupFailed'] as const;
const removedStates: readonly string[] = ['deleting', 'cleanupFailed', 'deleted'];
const fail = (status: number, code: string): never => { throw new AdminCatalogError(status, code); };
/** A lifecycle transaction with no role fence, for the cleanup pass that R9 runs without an administrator check. */
async function systemTransaction(work: (session: ClientSession) => Promise<void>) {
    const session = getDatabaseClient().startSession();
    try { await session.withTransaction(work, { readConcern: { level: 'snapshot' }, writeConcern: { w: 'majority' }, maxCommitTimeMS: 10_000 }); }
    finally { await session.endSession(); }
}

/** Uploads need the private staging bucket and the catalog bucket an approval copies into, as an approval does. */
export const catalogCoverStorageReady = () => importPrivateStorageReady() && Boolean(process.env.S3_BUCKET_NAME?.trim());

/** Checks kind, item id, intent key and storage before any body is read; the service repeats it. */
export function catalogCoverUploadPreflight(rawKind: unknown, ownerId: unknown, operationId: unknown): CatalogCoverKind {
    const kind = adminCatalogKind(rawKind);
    if (kind === 'organization') fail(400, 'ADMIN_CATALOG_COVER_UNSUPPORTED');
    if (!objectId(ownerId) || !uuid(operationId)) fail(400, 'ADMIN_CATALOG_INVALID_INPUT');
    if (!catalogCoverStorageReady()) fail(503, 'ADMIN_IMPORT_STORAGE_UNAVAILABLE');
    return kind as CatalogCoverKind;
}

/** The record id of one administrator's upload intent, derived as import projects derive theirs, so a replay finds its record. */
export const catalogCoverUploadId = (actor: string, operationId: string) => importDigest({ actor, operationId, purpose: 'catalogCoverUpload' }).slice(0, 24);
export const catalogCoverUploadFingerprint = (value: { kind: string; ownerId: string; sha256: string; byteLength: number; contentType: string; filename: string }) =>
    importDigest({ kind: value.kind, ownerId: value.ownerId, sha256: value.sha256, byteLength: value.byteLength, contentType: value.contentType, filename: value.filename });

/** Same validation as every cover (declared type, signature, size, pixels, complete decode), plus a single-frame check. */
export async function validateCatalogCoverUpload(file: Express.Multer.File): Promise<void> {
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.mimetype)) fail(400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    try { await validateCoverArtFile(file); }
    catch (error: any) { fail(error?.statusCode === 413 ? 413 : 400, error?.statusCode === 413 ? 'ADMIN_CATALOG_COVER_TOO_LARGE' : 'ADMIN_CATALOG_COVER_INVALID_IMAGE'); }
    if (await coverUploadMultiFrame(file.buffer, file.mimetype)) fail(400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
}

/** validateCoverArtFile decodes only the first frame: an animated WebP reports pages, and libvips reads an APNG as one frame. */
export async function coverUploadMultiFrame(buffer: Buffer, contentType: string): Promise<boolean> {
    if (contentType === 'image/webp') {
        try { return ((await sharp(buffer, { limitInputPixels: maxCoverArtInputPixels }).metadata()).pages ?? 1) > 1; }
        catch { return true; }
    }
    if (contentType !== 'image/png') return false;
    // An APNG declares its animation control chunk before the first image data chunk.
    for (let at = 8; at + 8 <= buffer.length; at += 12 + buffer.readUInt32BE(at)) {
        const type = buffer.toString('latin1', at + 4, at + 8);
        if (type === 'acTL') return true;
        if (type === 'IDAT') return false;
    }
    return false;
}

/** True when the first image chunk of a WebP is lossless (`VP8L`); `VP8X`, `ICCP`, `ANIM` and `ALPH` are skipped. */
function webpLossless(buffer: Buffer) {
    for (let at = 12; at + 8 <= buffer.length;) {
        const type = buffer.toString('latin1', at, at + 4), size = buffer.readUInt32LE(at + 4);
        if (type === 'VP8L') return true;
        if (type === 'VP8 ') return false;
        at += 8 + size + (size & 1);
    }
    return false;
}

/**
 * Follows normalizeAvatar (orientation applied, metadata removed, sRGB) but keeps format and pixel dimensions: no EXIF, XMP, IPTC,
 * PNG text or ICC profile is written. PNG and lossless WebP stay lossless; JPEG keeps 4:4:4 chroma when it had it.
 */
export async function normalizeCoverUpload(buffer: Buffer, contentType: string, maxBytes = maxCoverArtInputBytes): Promise<Buffer> {
    let output: Buffer;
    try {
        const image = sharp(buffer, { failOn: 'error', limitInputPixels: maxCoverArtInputPixels }), meta = await image.metadata();
        image.rotate();
        if (contentType === 'image/jpeg') image.jpeg({ quality: 92, mozjpeg: true, chromaSubsampling: meta.chromaSubsampling === '4:4:4' ? '4:4:4' : '4:2:0' });
        else if (contentType === 'image/png') image.png({ adaptiveFiltering: true, compressionLevel: 9 });
        else if (contentType === 'image/webp') image.webp(webpLossless(buffer) ? { lossless: true, exact: true } : { quality: 92 });
        else throw new Error('Unsupported cover type');
        output = await image.toBuffer();
    } catch { return fail(400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE'); }
    if (output.length > maxBytes) fail(413, 'ADMIN_CATALOG_COVER_TOO_LARGE');
    return output;
}

/**
 * Validates and normalizes before any write, admits a `pending` record bound to the item and its uploader, then stages the
 * normalized bytes privately. The catalog item is never written. Answers only once the staged object is confirmed.
 */
export async function uploadAdminCatalogCover(actor: string, rawKind: AdminCatalogKind, ownerId: string, operationId: unknown,
    file: Express.Multer.File | undefined, storage: ImportObjectStorage = defaultImportObjectStorage): Promise<{ upload: { id: string }; receipt: { operationId: string } }> {
    const kind = catalogCoverUploadPreflight(rawKind, ownerId, operationId), key = operationId as string;
    if (!file || !Buffer.isBuffer(file.buffer) || file.buffer.length !== file.size) return fail(400, 'ADMIN_CATALOG_INVALID_INPUT');
    await validateCatalogCoverUpload(file);
    // From here on only the normalized bytes are hashed, staged and approved.
    const normalized = await normalizeCoverUpload(file.buffer, file.mimetype);
    const filename = normalizeUtf8Text(file.originalname ?? '');
    if (!filename || filename.length > 255 || /[\u0000-\u001f\u007f-\u009f]/.test(filename)) fail(400, 'ADMIN_CATALOG_INVALID_INPUT');
    const sha256 = createHash('sha256').update(normalized).digest('hex'), byteLength = normalized.length, contentType = file.mimetype;
    const fingerprint = catalogCoverUploadFingerprint({ kind, ownerId, sha256, byteLength, contentType, filename }), _id = new ObjectId(catalogCoverUploadId(actor, key));
    // Every administrator transaction increments the same users document, so concurrent admissions by one administrator
    // write-conflict and retry: the bound is serialized per actor, and a concurrent duplicate retries into the replay path.
    await withCurrentAdministrator(actor, async session => {
        const prior = await uploads().findOne({ _id }, { session });
        if (prior) {
            if (prior.fingerprint !== fingerprint) fail(409, 'ADMIN_CATALOG_IDEMPOTENCY_CONFLICT');
            if (removedStates.includes(prior.asset.state)) fail(409, 'ADMIN_CATALOG_COVER_SOURCE_CHANGED');
            return;
        }
        if (!await readAdminCatalogRecord(kind, ownerId, session)) fail(404, 'ADMIN_CATALOG_NOT_FOUND');
        if (await uploads().countDocuments({ actorId: actor, usedBy: null, 'asset.state': { $in: [...liveStates] } }, { session, limit: COVER_UPLOAD_LIMITS.unused }) >= COVER_UPLOAD_LIMITS.unused) fail(429, 'ADMIN_CATALOG_COVER_UPLOAD_LIMIT');
        const now = new Date();
        await uploads().insertOne({ _id, kind, ownerId, actorId: actor, operationId: key, fingerprint, usedBy: null, createdAt: now, updatedAt: now,
            leaseOwner: null, leaseUntil: new Date(now.getTime() + COVER_UPLOAD_LIMITS.unusedMs),
            asset: { slotId: 'cover', operationId: key, actorId: actor, bucket: process.env.ADMIN_IMPORT_S3_BUCKET_NAME!.trim(), key: `imports/catalog-covers/${_id.toHexString()}`,
                sha256, byteLength, contentType, filename, state: 'pending', versionId: null, etag: null, updatedAt: now, leaseOwner: null, leaseUntil: null,
                transferDeadline: null, failureConfirmedAt: null, duration: null, format: null, representation: null, tags: null,
                recovery: { operationId: key, expectedRevision: 0, kind: 'upload', actorId: actor } } }, { session });
    });
    const state = await transferCatalogCoverUpload(actor, _id, sha256, normalized, file, storage);
    if (state !== 'ready') fail(503, 'ADMIN_CATALOG_COVER_UNKNOWN');
    return { upload: { id: _id.toHexString() }, receipt: { operationId: key } };
}

/**
 * HEAD/PUT/HEAD of the normalized bytes under an administrator-leased transfer, as transferImportAsset stages import files. The
 * outcome is lifecycle evidence written without a role check, and only while this transfer still holds a `pending` record, so a
 * transfer that outlived its lease never overwrites a record the cleanup pass marked for deletion; it answers 409 instead.
 */
export async function transferCatalogCoverUpload(actor: string, _id: ObjectId, sha256: string, normalized: Buffer, file: Express.Multer.File,
    storage: ImportObjectStorage): Promise<'ready' | 'unknown'> {
    const worker = randomUUID();
    const asset = await withCurrentAdministrator(actor, async session => {
        const record = await uploads().findOne({ _id }, { session }), now = Date.now();
        if (!record || record.asset.sha256 !== sha256) return fail(409, 'ADMIN_CATALOG_COVER_SOURCE_CHANGED');
        if (record.asset.state === 'ready') return null;
        if (removedStates.includes(record.asset.state)) fail(409, 'ADMIN_CATALOG_COVER_SOURCE_CHANGED');
        if (record.asset.leaseUntil && record.asset.leaseUntil.getTime() > now) fail(409, 'ADMIN_CATALOG_COVER_UPLOAD_BUSY');
        // The deadline bounds the HEAD and PUT aborts, so the cleanup pass can later prove absence.
        const lease = { 'asset.leaseOwner': worker, 'asset.leaseUntil': new Date(now + 300_000), 'asset.transferDeadline': new Date(now + ADMIN_IMPORT_LIMITS.uploadSettleMs),
            'asset.failureConfirmedAt': null, 'asset.state': 'pending' as const, 'asset.updatedAt': new Date(now), updatedAt: new Date(now) };
        await uploads().updateOne({ _id }, { $set: lease }, { session });
        return record.asset;
    });
    if (!asset) return 'ready';
    const target = importAssetTarget(_id.toHexString(), asset);
    let confirmed: ImportObjectIdentity | null = null, state: 'ready' | 'unknown' = 'unknown';
    try {
        confirmed = await storage.head(target);
        if (!confirmed) {
            try { confirmed = await storage.put(target, { ...file, buffer: normalized, size: normalized.length, path: undefined } as unknown as Express.Multer.File); }
            catch { confirmed = await storage.head(target); }
        }
        // A missing object after a failed PUT is not a confirmed failure: an SDK attempt may still land.
        state = confirmed ? 'ready' : 'unknown';
    } catch { state = 'unknown'; }
    const now = new Date();
    const written = await uploads().updateOne({ _id, 'asset.leaseOwner': worker, 'asset.state': 'pending' }, { $set: { 'asset.state': state, 'asset.etag': confirmed?.etag ?? null,
        'asset.versionId': confirmed?.versionId ?? null, 'asset.leaseOwner': null, 'asset.leaseUntil': null, 'asset.updatedAt': now, updatedAt: now } });
    if (written.matchedCount === 1) return state;
    // The lease ran out: a retry's transfer now owns a live record (its outcome decides), or the cleanup pass removed it.
    const current = await uploads().findOne({ _id }, { projection: { 'asset.state': 1 } });
    if (!current || !removedStates.includes(current.asset.state)) return 'unknown';
    // No transfer starts on a removed record, so this late one deletes the object it confirmed, by exact identity, rather than orphan it.
    if (confirmed) await storage.delete({ ...target, ...confirmed })
        .catch(() => console.warn(JSON.stringify({ category: 'admin_catalog_cover_upload_cleanup_failed', uploadId: _id.toHexString() })));
    return fail(409, 'ADMIN_CATALOG_COVER_SOURCE_CHANGED');
}

/**
 * Binds one ready upload to the approval admitted in the same transaction (mutateCover): only its uploader, its item and one
 * approval. The cleanup lease is freed, so the pass soon checks the approval's progress.
 */
export async function catalogCoverUploadSource(session: ClientSession, actor: string, kind: CatalogCoverKind, ownerId: string, uploadId: string,
    operationHex: string, now = new Date()): Promise<ImportAsset> {
    const record = await uploads().findOne({ _id: new ObjectId(uploadId) }, { session });
    if (!record || record.kind !== kind || record.ownerId !== ownerId || record.actorId !== actor || record.usedBy !== null
        || record.asset.state !== 'ready' || !record.asset.etag) return fail(409, 'ADMIN_CATALOG_COVER_SOURCE_CHANGED');
    if (record.asset.byteLength > maxCoverArtInputBytes) fail(409, 'ADMIN_IMPORT_ASSET_CONFLICT');
    const used = await uploads().updateOne({ _id: record._id, usedBy: null, 'asset.state': 'ready' }, { $set: { usedBy: operationHex, updatedAt: now, leaseUntil: now } }, { session });
    if (used.matchedCount !== 1) fail(409, 'ADMIN_CATALOG_COVER_SOURCE_CHANGED');
    return structuredClone(record.asset);
}

/**
 * Whether the pass may delete a staged upload: only once its transfer settled, and when unused a day after upload, or when the
 * approval that used it is complete (its cleanup flag concerns the previous image) or cancelled with its cleanup confirmed.
 */
export function coverUploadDeletable(upload: Pick<CatalogCoverUpload, 'usedBy' | 'createdAt' | 'asset'>, operation: { state: string; cleanupPending: boolean } | null, now: Date): boolean {
    if (!importUploadSettled(upload.asset, now)) return false;
    if (upload.usedBy === null) return now.getTime() - upload.createdAt.getTime() >= COVER_UPLOAD_LIMITS.unusedMs;
    if (!operation) return false;
    if (operation.state === 'complete') return true;
    return operation.state === 'cancelled' && !operation.cleanupPending;
}

/**
 * One cleanup pass over the oldest due upload. Deletes only a private staged object its own record names, which no catalog record
 * references and no unfinished approval uses; R9 has no administrator check. A kept upload is checked again an hour later, and a
 * failed deletion is logged and retried an hour later. Returns whether a record was claimed.
 */
export async function runCatalogCoverUploadCleanupOnce(storage: ImportObjectStorage = defaultImportObjectStorage, signal?: AbortSignal, now: Date = new Date()): Promise<boolean> {
    if (signal?.aborted || !importPrivateStorageReady()) return false;
    const worker = randomUUID(), later = (ms: number) => new Date(now.getTime() + ms);
    const claimed = await uploads().findOneAndUpdate({ 'asset.state': { $in: [...liveStates] }, leaseUntil: { $lte: now } },
        { $set: { leaseOwner: worker, leaseUntil: later(COVER_UPLOAD_LIMITS.leaseMs) } }, { sort: { leaseUntil: 1 }, returnDocument: 'after' });
    const upload = claimed.value; if (!upload) return false;
    // Reset in the callback, which may run more than once.
    let decision = 'none' as 'none' | 'keep' | 'delete', asset = upload.asset;
    await systemTransaction(async session => {
        decision = 'none';
        const current = await uploads().findOne({ _id: upload._id, leaseOwner: worker }, { session }); if (!current) return;
        asset = current.asset;
        if (current.asset.state === 'deleting' || current.asset.state === 'cleanupFailed') { decision = 'delete'; return; }
        const operation = current.usedBy && objectId(current.usedBy) ? await getDb()!.collection('adminCatalogCoverOperations')
            .findOne({ _id: new ObjectId(current.usedBy) }, { session, projection: { state: 1, cleanupPending: 1 } }) : null;
        // These writes conflict with a racing approval of the same upload: either it is bound and kept, or it is deleted first.
        if (coverUploadDeletable(current, operation ? { state: String(operation.state), cleanupPending: Boolean(operation.cleanupPending) } : null, now)) {
            await uploads().updateOne({ _id: upload._id, leaseOwner: worker }, { $set: { 'asset.state': 'deleting', 'asset.leaseOwner': null, 'asset.leaseUntil': null, 'asset.updatedAt': now, updatedAt: now } }, { session });
            decision = 'delete';
        } else {
            await uploads().updateOne({ _id: upload._id, leaseOwner: worker }, { $set: { leaseOwner: null, leaseUntil: later(COVER_UPLOAD_LIMITS.retryMs), updatedAt: now } }, { session });
            decision = 'keep';
        }
    });
    if (decision !== 'delete') return true;
    const target = importAssetTarget(upload._id.toHexString(), asset);
    try {
        checkAdminWorker(signal);
        const identity = await storage.head(target, signal);
        if (identity) { checkAdminWorker(signal); await storage.delete({ ...target, ...identity }); }
        checkAdminWorker(signal);
        if (await storage.head(target, signal)) throw new Error('Staged cover upload still present');
        await uploads().updateOne({ _id: upload._id, leaseOwner: worker }, { $set: { 'asset.state': 'deleted', 'asset.updatedAt': now, updatedAt: now, leaseOwner: null, leaseUntil: null } });
    } catch {
        // A stopping worker writes nothing: the claim waits out its lease and the next pass resumes from `deleting`.
        if (signal?.aborted) return true;
        await uploads().updateOne({ _id: upload._id, leaseOwner: worker }, { $set: { 'asset.state': 'cleanupFailed', updatedAt: now, leaseOwner: null, leaseUntil: later(COVER_UPLOAD_LIMITS.retryMs) } });
        console.warn(JSON.stringify({ category: 'admin_catalog_cover_upload_cleanup_failed', uploadId: upload._id.toHexString() }));
    }
    return true;
}
